{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "苟小闲",
      "role": "protagonist",
      "identity": "数据录入员/剧场玩家",
      "traits": ["极度怕死", "机智狡猾", "吐槽狂魔", "表面怂包", "内心有正义感"],
      "overt_motivation": "找到退出剧场的方法，回归正常的躺平生活",
      "covert_motivation": "证明自己不只是个懦夫，渴望在关键时刻能够挺身而出获得认可",
      "secret_fear": "发现自己其实是个真正的懦夫，在生死关头会抛弃他人独自逃命",
      "misperception_of_other": "认为周影是个冷酷无情、只在乎通关的资深玩家，不懂她为何总救自己",
      "hidden_connection": "他的入职时间和剧场系统的启动时间高度重合，暗示他可能是系统设计的原生NPC觉醒者"
    },
    {
      "name": "周影",
      "role": "deuteragonist",
      "identity": "资深玩家/前特种兵",
      "traits": ["冷静果断", "身手敏捷", "神秘寡言", "外冷内热", "执念深重"],
      "overt_motivation": "通关剧场达到最高层，揭开系统的真相",
      "covert_motivation": "寻找三年前在剧场失踪的弟弟周辰，不相信他已经死亡",
      "secret_fear": "发现自己其实已经不在乎弟弟的生死了，只是在用寻找当借口逃避现实",
      "misperception_of_other": "最初认为苟小闲是个靠运气苟活的废物，后来逐渐发现他的观察力和推理能力",
      "hidden_connection": "她弟弟周辰的失踪与苟小闲的入职时间吻合，暗示两人命运的交织"
    }
  ],
  "supporting_characters": [
    {
      "name": "钱多多",
      "function": "助力",
      "identity": "剧场老玩家/情报商人",
      "description": "在剧场中经营情报和道具交易的商人，表面唯利是图，实则重情义。他掌握着大量副本规则和玩家情报，曾多次帮助苟小闲和周影，但帮忙的方式总是需要付出代价或完成交换。他是个中年油腻大叔，说话油腔滑调但关键时刻可靠。"
    },
    {
      "name": "零号管理员",
      "function": "阻碍",
      "identity": "剧场系统的高级NPC/守密者",
      "description": "剧场系统的最高级别管理员，以白色西装、无面目的形象出现。他负责维持剧场运转，对试图揭露系统真相的玩家进行抹杀。他看似无情，但偶尔会透露出一些关于剧场起源的只言片语，暗示他并非完全的反派。"
    },
    {
      "name": "白夜",
      "function": "反转点",
      "identity": "神秘玩家/反抗军领袖",
      "description": "一个传说级的玩家，据说已经通关了剧场最顶层却从未离开。他在暗中组织反抗军，试图从内部摧毁剧场系统。他知晓剧场的核心秘密，并在关键时刻向苟小闲揭示了一个惊人的真相：剧场并非游戏，而是某种筛选机制。"
    },
    {
      "name": "老吴",
      "function": "助力",
      "identity": "苟小闲的现实同事/同为玩家",
      "description": "苟小闲在现实中的同事，也是剧场的低级玩家。他是个老实巴交的中年人，和苟小闲一样只想苟活。他在现实中给苟小闲提供掩护，在剧场中则互相照应，是苟小闲在现实与剧场之间的纽带。"
    }
  ],
  "relationship_dynamics": "苟小闲和周影的关系经历了四个阶段：第一阶段（初遇-不信任）在第一个副本中，苟小闲认为周影是个冷酷的杀人机器，周影则觉得苟小闲是个靠运气苟活的累赘；第二阶段（被迫合作-互相依赖）在第二个副本中，两人被迫组队，苟小闲发现周影每次都在暗中保护自己，周影也开始认可苟小闲的观察力和推理能力；第三阶段（信任危机-身份揭露）周影发现苟小闲可能是系统设计的原生NPC，怀疑他接近自己的目的，两人关系破裂；第四阶段（和解-并肩作战）在最终真相揭露后，两人理解彼此都是被命运摆布的棋子，选择联手对抗系统。"
}
"}

